  const legend = () => `<div class="legend"><b>How to read every screen:</b><span><i class="dot g"></i>active, firing or running</span><span><i class="dot a"></i>draft, or something to decide here</span><span><i class="dot p"></i>follows the library</span><span><i class="dot o"></i>placeholder: a decision still pending</span></div>`;
  const topbar = () => `<header class="topbar"><div class="burger"><i></i><i></i><i></i></div><div class="logo"><span>💧</span><div>Digital<b>Paani</b><small>Close the Loop · v3</small></div></div><span class="spacer"></span><button class="btn sm" id="helpBtn" style="border-color:rgba(255,255,255,.4);background:transparent;color:#fff" title="How this screen works, who may change what, and what every term means">? Help</button><a class="plain" href="index.html">Hand-off doc</a><select id="persona" title="Who is signed in (roles come from User Center)">${Object.entries(PERSONA).map(([k, p]) => `<option value="${k}" ${S.persona === k ? 'selected' : ''}>${p.label} — ${p.who.split(' ')[0]}</option>`).join('')}</select><button class="btn sm" id="reset" style="border-color:rgba(255,255,255,.4);background:transparent;color:#fff">Reset data</button><span class="icon">🔔</span><span class="icon">💬<span class="badge">99+</span></span><span class="user"><span class="av">👤</span>${esc(PERSONA[S.persona].who)}</span></header>`;
  const crumbs = (items) => `<nav class="crumbs">${items.map((it, i) => `${i ? '<span class="sep">›</span>' : ''}${it.href ? `<a href="${it.href}">${esc(it.label)}</a>` : `<b>${esc(it.label)}</b>`}`).join('')}</nav>`;
