    const head = `${crumbs([{ label: 'Close the Loop' }, { label: 'Configuration' }, { label: 'Library' }])}${topTabs('library')}<h1 class="pagetitle">Library</h1><p class="lede">${editor ? 'The perfect picture every plant inherits: what each machine type, stage and plant type should have. Open anything to edit it. Changes go into a draft; nothing reaches a plant until you publish a new version.' : 'The perfect picture every plant inherits: what each machine type, stage and plant type should have. Open anything to see what it holds. A Global Admin edits it.'}</p>`;
    const status = editor ? (d ? banner('warn', `<b>Draft based on v${esc(d.base)}:</b> ${plural(d.changes.length, 'change')}${d.changes.length ? ' · ' + d.changes.slice(0, 3).map(esc).join(' · ') + (d.changes.length > 3 ? ' …' : '') : ''}. Plants keep v${esc(LIBRARY.version)} until you publish.`, `<button class="btn sm" id="libDiscard">Discard draft</button><button class="btn sm primary" id="libPublish" ${d.changes.length ? '' : 'disabled'}>Review and publish</button>`) : banner('', `Published version <b>v${esc(LIBRARY.version)}</b>. Your first change starts a draft.`)) : banner('', `Published version <b>v${esc(LIBRARY.version)}</b>. Read-only for ${esc(PERSONA[S.persona].label)}.`);
    const tabs = `<div class="tabs">${LIB_SECTIONS.map(([k, l]) => `<a href="#/library/${k}" class="${sec === k ? 'on' : ''}">${l}</a>`).join('')}</div>`;
    const ch = (kind, key) => (libChanged(kind, key) ? chip('amber sm', 'Changed in draft') : '');
    const row = (attr, title, sub, chips, cls) => `<div class="row click ${cls || ''}" ${attr}><div><div class="t">${title}</div><div class="s">${sub}</div></div><div class="chips">${chips}<span class="chev" aria-hidden="true">›</span></div></div>`;
