    if (sec === 'types') { const list = L.equipmentTypes.filter((t) => match(q, t.type, t.archetype)).sort((a, b) => (a.retired - b.retired) || a.type.localeCompare(b.type)); body = `<div class="toolbar">${search('Search equipment types')}${add('libAddType', 'Equipment type')}</div>${list.map((t) => { const use = C.plantsUsingType(t.type); const pre = t.readings.filter((r) => r.preset).length; return row(`data-lib="type:${esc(t.type)}"`, `${esc(t.type)} ${chip('off sm', 'tier ' + t.tier)}${t.retired ? chip('off sm', 'Retired') : ''}`, `${plural(t.readings.length, 'sensor')}${t.readings.length ? ` (${pre} with preset bands)` : ''} · ${plural(t.alerts.length, 'alert')} · ${plural(t.schedules.length, 'schedule')}${(L.expects.byGroupType[t.type] || []).length ? ` · ${plural(L.expects.byGroupType[t.type].length, 'group sensor')}` : ''} · ${use.machines ? `${plural(use.machines, 'machine')} at ${plural(use.plants, 'plant')}` : 'not used at any plant'}`, ch('type', t.type), t.retired ? 'retired' : ''); }).join('') || empty('No type matches', '')}`; }
