    if (kind === 'flow') { const o = key ? L.flows.find((f) => f.id === key) : null; x = o ? C.clone(o) : { id: '', name: '', use: 'fix', forTypes: [], forStage: null, steps: 0, version: 1 }; x.__steps = C.clone(L.flowSteps[key] || (o ? C.flowSteps(o) : [])); }
